import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), sceneRoot=$('#scene');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x89949a);scene.fog=new THREE.FogExp2(0x89949a,.012);
const camera=new THREE.PerspectiveCamera(67,innerWidth/innerHeight,.1,260);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;sceneRoot.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc8d4d7,0x312c29,1.4));const sun=new THREE.DirectionalLight(0xffdfae,2.1);sun.position.set(-35,50,24);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-60;sun.shadow.camera.right=60;sun.shadow.camera.top=60;sun.shadow.camera.bottom=-60;scene.add(sun);
const mat=(color,roughness=.9,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const groundMat=mat(0x393d3b), stone=mat(0x535550), darkStone=mat(0x303638), paleStone=mat(0x77766c), gold=mat(0xb69b69,.52,.45), bark=mat(0x352f2b), leaf=mat(0x263936), crystalMat=new THREE.MeshStandardMaterial({color:0x9be5df,emissive:0x1b8c91,emissiveIntensity:1.2,roughness:.22,metalness:.2}), glowMat=new THREE.MeshBasicMaterial({color:0xa9f5e8});
const floor=new THREE.Mesh(new THREE.PlaneGeometry(230,230),groundMat);floor.rotation.x=-Math.PI/2;floor.position.y=-.14;floor.receiveShadow=true;scene.add(floor);
// Broken basalt Causeway, leading from the pilgrim gate toward a drowned cloister.
function box(x,y,z,sx,sy,sz,material=stone,rot=0){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.rotation.y=rot;m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
function cylinder(x,y,z,rt,rb,h,material=stone,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
function rock(x,z,s=1){const m=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),Math.random()<.5?stone:darkStone);m.position.set(x,s*.48-0.1,z);m.rotation.set(Math.random(),Math.random(),Math.random());m.scale.set(1+Math.random(),.7+Math.random()*.7,.8+Math.random());m.castShadow=true;m.receiveShadow=true;scene.add(m)}
// Causeway slabs
for(let i=0;i<38;i++){const z=35-i*2.15,x=Math.sin(i*.46)*2.1;let tile=box(x,.015,z,3.8+Math.random()*1.5,.18,2.1, i%4===0?darkStone:stone,Math.random()*.12);tile.position.x=x;}
// Ruined arch at the arrival point
for(const x of [-4.3,4.3]){cylinder(x,3,25,.5,.72,6,paleStone,7);cylinder(x,6.1,25,.58,.58,.3,gold,7)}box(0,6.2,25,9,.55,.75,paleStone,.03);box(0,6.6,25,4,.2,.4,gold,.03);
// A field of broken monoliths and fallen masonry
for(let i=0;i<30;i++){const x=(Math.random()-.5)*68,z=-8-Math.random()*48;if(Math.abs(x)<4&&z>0)continue;const h=1+Math.random()*5;const m=box(x,h/2,z,.65+Math.random()*1.2,h,.7+Math.random(),i%3?stone:paleStone,Math.random()*1.2);if(Math.random()<.6){m.rotation.z=(Math.random()-.5)*.4;m.rotation.x=(Math.random()-.5)*.3}if(i%3===0)box(x+1,.18,z+1,2.3,.3,1.5,darkStone,Math.random())}
// Drowned cloister, columns around a mirror pool
for(let i=0;i<12;i++){const a=i*Math.PI/6,x=19+Math.cos(a)*10,z=-23+Math.sin(a)*10;cylinder(x,2.05,z,.42,.55,4.1,paleStone,8);cylinder(x,4.2,z,.62,.62,.24,gold,8)}
const pool=new THREE.Mesh(new THREE.CircleGeometry(7.7,48),new THREE.MeshStandardMaterial({color:0x25383a,metalness:.55,roughness:.23,transparent:true,opacity:.88}));pool.rotation.x=-Math.PI/2;pool.position.set(19,.02,-23);scene.add(pool);
for(let i=0;i<8;i++){const a=i*Math.PI/4;box(19+Math.cos(a)*10,4.28,-23+Math.sin(a)*10,2.3,.3,1.4,paleStone,a)}
// Glasswood: slender dark trunks with clustered muted crowns.
for(let i=0;i<56;i++){const x=-37+Math.random()*24,z=-10-Math.random()*54;if(Math.abs(x)<7&&z>-30)continue;const h=4+Math.random()*5;cylinder(x,h/2,z,.12,.24,h,bark,6);for(let j=0;j<3;j++){const c=new THREE.Mesh(new THREE.IcosahedronGeometry(1.3+Math.random()*.8,1),leaf);c.position.set(x+(Math.random()-.5),h*.55+j*.75,z+(Math.random()-.5));c.scale.y=.8;c.castShadow=true;scene.add(c)}}
// Basalt ridge teeth and distant mountains
for(let i=0;i<20;i++){const side=i%2?1:-1,x=side*(26+Math.random()*19),z=-6-Math.random()*55,h=8+Math.random()*16;const m=new THREE.Mesh(new THREE.ConeGeometry(3+Math.random()*4,h,5),darkStone);m.position.set(x,h/2-1,z);m.rotation.y=Math.random();m.castShadow=true;scene.add(m)}
// Gold-leaf grass patches
const grassMat=new THREE.MeshStandardMaterial({color:0x77724f,side:THREE.DoubleSide});for(let i=0;i<190;i++){const g=new THREE.Mesh(new THREE.ConeGeometry(.12,.6,3),grassMat);g.position.set((Math.random()-.5)*74,.18,-Math.random()*74);g.rotation.z=(Math.random()-.5)*.35;scene.add(g)}
// Shrine on the far rise; its ring turns slowly.
const shrine=new THREE.Group();shrine.position.set(-19,0,-45);scene.add(shrine);for(let i=0;i<7;i++){const a=i*2*Math.PI/7;const p=new THREE.Mesh(new THREE.CylinderGeometry(.45,.65,2.6,7),paleStone);p.position.set(Math.cos(a)*3,1.3,Math.sin(a)*3);p.castShadow=true;shrine.add(p)}const dais=new THREE.Mesh(new THREE.CylinderGeometry(4.5,5,.65,12),darkStone);dais.position.y=.2;dais.castShadow=true;shrine.add(dais);const ring=new THREE.Mesh(new THREE.TorusGeometry(2.15,.12,8,48),gold);ring.position.y=3.1;ring.rotation.x=.45;shrine.add(ring);const altar=new THREE.Mesh(new THREE.OctahedronGeometry(.8,1),crystalMat);altar.position.y=3.2;shrine.add(altar);
// Small suspended lights and drifting ash
const motes=new THREE.Group();scene.add(motes);for(let i=0;i<125;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.035+Math.random()*.04,5,5),new THREE.MeshBasicMaterial({color:i%3===0?0xc1aa79:0x9abbb5,transparent:true,opacity:.35+Math.random()*.4}));m.position.set((Math.random()-.5)*75,Math.random()*13,-Math.random()*80);m.userData.phase=Math.random()*6.28;motes.add(m)}
// Interactive echo crystals
const echoes=[];const echoPlaces=[[-9,1,-10],[24,1,-23],[-22,1,-43]];for(let i=0;i<3;i++){const group=new THREE.Group();group.position.set(...echoPlaces[i]);scene.add(group);const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.8,.1),crystalMat);crystal.position.y=1.4;crystal.castShadow=true;group.add(crystal);const hoop=new THREE.Mesh(new THREE.TorusGeometry(1.2,.035,6,40),gold);hoop.position.y=1.35;hoop.rotation.x=Math.PI/2;group.add(hoop);const light=new THREE.PointLight(0x69d8d1,2.2,8);light.position.y=1.5;group.add(light);echoes.push({group,crystal,active:true,index:i})}
// Player model and wandering shade
const player=new THREE.Group();scene.add(player);const body=new THREE.Mesh(new THREE.CapsuleGeometry(.38,.85,4,8),mat(0x303940,.7,.25));body.position.y=.9;body.castShadow=true;player.add(body);const mantle=new THREE.Mesh(new THREE.ConeGeometry(.55,1.25,7),mat(0x5c5143));mantle.position.set(0,.78,-.18);mantle.rotation.x=-.13;mantle.castShadow=true;player.add(mantle);const hood=new THREE.Mesh(new THREE.SphereGeometry(.28,10,8),mat(0x191f21));hood.position.set(0,1.65,.03);player.add(hood);const eyeGlow=new THREE.PointLight(0xb1ded2,.5,2);eyeGlow.position.set(0,1.65,.3);player.add(eyeGlow);
const shade=new THREE.Group();scene.add(shade);const shadeMat=new THREE.MeshStandardMaterial({color:0x101618,emissive:0x163233,emissiveIntensity:.7,transparent:true,opacity:.88});const shadeBody=new THREE.Mesh(new CapsuleGeometryFallback(),shadeMat);shadeBody.position.y=1.2;shade.add(shadeBody);for(let i=0;i<3;i++){const tend=new THREE.Mesh(new THREE.ConeGeometry(.24,1.7,5),shadeMat);tend.position.set((i-1)*.34,.4,-.14);tend.rotation.z=(i-1)*.27;shade.add(tend)}const shadeLight=new THREE.PointLight(0x2daba5,2.5,7);shadeLight.position.y=1.5;shade.add(shadeLight);shade.position.set(35,0,-37);
function CapsuleGeometryFallback(){return new THREE.CapsuleGeometry(.5,.9,4,8)}
let started=false,chosen='lumen',collected=0,view='third',paused=false,hasFocus=false,health=100,cooldown=0,elapsed=0,shadeAwake=false,complete=false,sound=true;const keys={},touch={};let yaw=0,pitch=-.12,velocity=new THREE.Vector3(),lastPosition=new THREE.Vector3();const clock=new THREE.Clock();
const paths={lumen:{name:'Aureole · The Pale Ward',flaw:'Afterglow',gift:'AUREOLE',desc:'A ring of pale light reveals and staggers shades',true:['VESPER, WHO KEEPS THE UNLIT','ORIEL, AT THE LAST LANTERN','SABLE, UNDER A SILENT STAR'],vow:['I will carry what the dark abandons','I will not be made into a weapon','I will leave a road behind me']},echo:{name:'Reprise · The Borrowed Moment',flaw:'Borrowed Breath',gift:'REPRISE',desc:'Return to where you stood a heartbeat ago',true:['MORROW, TWICE REMEMBERED','TALEN, WHO WALKED BACKWARD','EIDOL, IN THE SECOND DAWN'],vow:['I will choose what comes next','I will not be made into a weapon','I will leave a road behind me']},thorn:{name:'Grasp · The Far Tether',flaw:'Open Vein',gift:'GRASP',desc:'A spectral tether draws you toward an anchor',true:['BRIAR, BENEATH THE STONE','VALE, WHO HOLDS THE DISTANCE','KETH, THE UNBROKEN ROOT'],vow:['I will go where the road ends','I will not be made into a weapon','I will leave a road behind me']}};
function tell(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(tell.timer);tell.timer=setTimeout(()=>t.classList.remove('show'),2500)}function updateIdentity(){const p=paths[chosen],i=Math.floor(Math.random()*p.true.length);$('#trueName').textContent=p.true[i];$('#vowName').textContent=p.vow[i];$('#powerName').textContent=p.name;$('#flawName').textContent=p.flaw;$('#abilityName').textContent=`${p.gift} · Q`;$('#abilityDesc').textContent=p.desc}
function region(){const p=player.position;if(p.z>4)return ['CINDER CAUSEWAY','A road of black glass leads through the old pilgrim ruins.'];if(p.x>6&&p.z>-35)return ['DROWNED CLOISTER','A mirror pool holds the last light beneath a ring of broken arches.'];if(p.x<-12&&p.z<-30)return ['THE LAST ALTAR','Seven silent pillars keep watch over a restless shard.'];if(p.x<-9)return ['GLASSWOOD','Brittle boughs whisper against one another in the ash-wind.'];return ['CINDER EXPANSE','Basalt teeth mark the old pilgrim road.']}
function openPath(){updateIdentity();$('#pathModal').classList.remove('hidden')}
function begin(){if(started)return;$('#intro').classList.add('hidden');$('#gameUI').classList.remove('hidden');started=true;openPath();requestLock()}
function requestLock(){if(innerWidth>700&&document.pointerLockElement!==renderer.domElement)renderer.domElement.requestPointerLock?.()}
$('#begin').onclick=begin;$('#pathModal').querySelectorAll('.path').forEach(el=>el.onclick=()=>{$('#pathModal .selected')?.classList.remove('selected');el.classList.add('selected');chosen=el.dataset.path;updateIdentity()});$('#confirmPath').onclick=()=>{$('#pathModal').classList.add('hidden');tell(`THE REACH HEARS YOU: ${paths[chosen].true[0].split(',')[0]}`);requestLock()};$('#pauseBtn').onclick=()=>togglePause(true);$('#resume').onclick=()=>togglePause(false);$('#restart').onclick=()=>location.reload();function togglePause(v){paused=v;$('#pauseModal').classList.toggle('hidden',!v);if(v)document.exitPointerLock?.();else requestLock()}
$('#viewBtn').onclick=()=>{view=view==='third'?'first':'third';$('#viewBtn').textContent=view==='third'?'◉ THIRD PERSON':'◉ FIRST PERSON';player.children.forEach(c=>c.visible=view==='third');tell(`${view.toUpperCase()} VIEW`)};$('#soundBtn').onclick=()=>{sound=!sound;$('#soundBtn').textContent=sound?'♪ SOUND ON':'♪ SOUND OFF';$('#soundBtn').classList.toggle('sound-off',!sound)};
document.addEventListener('pointerlockchange',()=>{hasFocus=document.pointerLockElement===renderer.domElement});document.addEventListener('mousemove',e=>{if(hasFocus&&!paused){yaw-=e.movementX*.0022;pitch=Math.max(-.75,Math.min(.38,pitch-e.movementY*.0018))}});document.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='e')interact();if(e.key.toLowerCase()==='q')gift();if(e.key==='Escape'&&started)togglePause(!paused)});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);renderer.domElement.addEventListener('click',()=>{if(started&&!paused&&!$('#pathModal').classList.contains('hidden'))return;requestLock()});
$('#mobileUse').onclick=interact;$('#mobileGift').onclick=gift;document.querySelectorAll('[data-move]').forEach(b=>{const k=b.dataset.move;b.addEventListener('pointerdown',e=>{e.preventDefault();touch[k]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>touch[k]=false))});
function closestTarget(){let best=null,d=4;for(const e of echoes){if(!e.active)continue;const dist=player.position.distanceTo(e.group.position);if(dist<d){best=e;d=dist}}if(collected===3&&player.position.distanceTo(shrine.position)<7)return {shrine:true};return best}
function interact(){if(!started||paused||!$('#pathModal').classList.contains('hidden'))return;const target=closestTarget();if(target?.shrine){complete=true;$('#objectiveTitle').textContent='THE OATH IS YOURS';$('#objectiveText').textContent='The Reach opens beyond the altar';tell('The altar answers. Your next road is yours to choose.');return}if(!target){tell('Only wind answers. Draw closer to an echo.');return}target.active=false;target.group.visible=false;collected++;shadeAwake=true;$('#progressText').textContent=`ECHOES ${collected} / 3`;$('#progressBar').style.width=`${collected/3*100}%`;if(collected===3){$('#objectiveTitle').textContent='THE LAST ALTAR';$('#objectiveText').textContent='Carry the echoes to the shrine in the west';tell('All three echoes gathered. The altar stirs to the west.')}else tell(`ECHO FRAGMENT ${collected} / 3 GATHERED`)}
function gift(){if(!started||paused||cooldown>0)return;if(chosen==='lumen'){const light=new THREE.PointLight(0xa6fff0,8,16);light.position.copy(player.position).add(new THREE.Vector3(0,2,0));scene.add(light);setTimeout(()=>scene.remove(light),700);if(shadeAwake&&player.position.distanceTo(shade.position)<14){shade.position.set(40,0,-42);tell('AUREOLE — the shade recoils from your light.')}else tell('AUREOLE — hidden paths shimmer in the pale ward.')}else if(chosen==='echo'){player.position.copy(lastPosition);velocity.set(0,0,0);tell('REPRISE — the moment folds back around you.')}else{const direction=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));player.position.addScaledVector(direction,8);health=Math.max(24,health-7);tell('GRASP — the tether pulls; the thorn takes its due.')}cooldown=5;$('#abilityDesc').textContent='Gift recovering · 5s'}
function update(dt){elapsed+=dt;cooldown=Math.max(0,cooldown-dt);if(cooldown===0)$('#abilityDesc').textContent=paths[chosen].desc;const forward=(keys.w||keys.arrowup||touch.w?1:0)-(keys.s||keys.arrowdown||touch.s?1:0),side=(keys.d||keys.arrowright||touch.d?1:0)-(keys.a||keys.arrowleft||touch.a?1:0);const speed=(keys.shift?8:5.2);const dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw)),right=new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw));const move=dir.multiplyScalar(forward).add(right.multiplyScalar(side));if(move.lengthSq()>0){move.normalize();lastPosition.copy(player.position);player.position.addScaledVector(move,speed*dt);player.rotation.y=Math.atan2(-move.x,-move.z)}player.position.x=THREE.MathUtils.clamp(player.position.x,-47,47);player.position.z=THREE.MathUtils.clamp(player.position.z,-72,42);const [rn,rd]=region();$('#regionName').textContent=rn;$('#regionDesc').textContent=rd;
for(const e of echoes)if(e.active){e.group.rotation.y+=dt*.32;e.crystal.position.y=1.4+Math.sin(elapsed*1.6+e.index)*.18;e.group.children[2].intensity=2+Math.sin(elapsed*2+e.index)*.6}
ring.rotation.z+=dt*.18;altar.rotation.y+=dt*.45;for(const m of motes.children){m.position.y+=Math.sin(elapsed+m.userData.phase)*dt*.12;m.position.x+=Math.cos(elapsed*.3+m.userData.phase)*dt*.045}
if(shadeAwake){const to=player.position.clone().sub(shade.position);to.y=0;const dist=to.length();if(dist>1.8){to.normalize();shade.position.addScaledVector(to,dt*(collected===3?2.45:1.75));shade.rotation.y=Math.atan2(-to.x,-to.z)}shade.position.y=.12+Math.sin(elapsed*3)*.14;if(dist<1.8&&elapsed>2){health-=dt*10;if(health<1){health=100;player.position.set(0,0,32);shade.position.set(35,0,-37);tell('The shade unmade your trail. The causeway takes you back.')}}}const target=closestTarget();if(target&&started&&!paused)$('#objectiveText').textContent=target.shrine?'Press E to touch the altar':`Press E to gather echo ${collected+1}`;
const look=new THREE.Vector3(-Math.sin(yaw)*Math.cos(pitch),Math.sin(pitch),-Math.cos(yaw)*Math.cos(pitch));if(view==='first'){camera.position.copy(player.position).add(new THREE.Vector3(0,1.6,0));camera.lookAt(camera.position.clone().add(look))}else{const offset=new THREE.Vector3(Math.sin(yaw)*5.5,2.5+pitch*2,Math.cos(yaw)*5.5);camera.position.lerp(player.position.clone().add(offset),1-Math.pow(.0005,dt));camera.lookAt(player.position.clone().add(new THREE.Vector3(0,1.35,0)).add(look.multiplyScalar(2)))} }
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.04);if(!paused)update(dt);renderer.render(scene,camera)}animate();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

